        } catch (_: Exception) {
            return null
        }
    val rawUserInfo = uri.rawUserInfo ?: return null
    if (rawUserInfo.isEmpty()) return null
    val decoded = java.net.URLDecoder.decode(rawUserInfo, Charsets.UTF_8)
    val encoded =
        java.util.Base64
            .getEncoder()
            .encodeToString(decoded.toByteArray(Charsets.UTF_8))
    return "Basic $encoded"
}

/**
 * Normalize a URI port, returning the default-port value (443 for https,
 * 80 for http) when the URI does not specify an explicit port. Used by
 * the same-origin redirect check so that `https://host/x` and
 * `https://host:443/x` compare equal — without this, a redirect that
 * only adds the implicit default port would incorrectly be treated as
 * cross-origin and strip sensitive headers (Authorization, Cookie,
 * Proxy-Authorization).
 */
internal fun effectivePort(uri: java.net.URI): Int {
    val port = uri.port
    if (port != -1) return port
    return if ("https".equals(uri.scheme, ignoreCase = true)) 443 else 80
}

/**
 * Decide whether two URIs share the same origin (scheme + host + effective
 * port) for forwarding sensitive headers across a redirect. The scheme MUST
 * match: redirecting from `https://host/x` to `http://host/x` is a TLS
 * downgrade and must drop the Authorization header.
 */
internal fun sameOrigin(
    originalUri: java.net.URI,
    redirectUri: java.net.URI,
): Boolean =
    redirectUri.host != null &&
        redirectUri.scheme != null &&
        originalUri.scheme != null &&
        redirectUri.scheme.equals(originalUri.scheme, ignoreCase = true) &&
        redirectUri.host.equals(originalUri.host, ignoreCase = true) &&
        effectivePort(redirectUri) == effectivePort(originalUri)

/**
 * Resolve a Location header against the URL that produced it. java.net.URI
 * implements the RFC 2396 rules, which resolve a query-only reference such as
 * `?page=2`, or an empty one, against the base DIRECTORY (dropping the last
 * path segment); RFC 3986 keeps the base path (and, for an empty reference,
 * the base query). A fragment-only reference is already resolved the RFC 3986
 * way by java.net.URI, and every other reference form resolves identically
 * under both RFCs, so only the query-only and empty forms are handled here.
 */
internal fun resolveRedirectLocation(
    base: java.net.URI,
    location: String,
): java.net.URI {
    if (location.isEmpty()) {
        return java.net.URI(base.toString().substringBefore('#'))
    }
    if (location.startsWith("?")) {
        val baseWithoutQuery = base.toString().substringBefore('#').substringBefore('?')
        return java.net.URI(baseWithoutQuery + location)
    }
    return base.resolve(location)
}

/**
 * Resolve a Location header for following, or null when it is unusable: absent,
 * empty, or rejected by the reference resolver (`http://[bad`). The redirect
 * loop treats null exactly like a missing Location and returns the 3xx as-is.
 */
internal fun usableRedirectLocation(
    base: java.net.URI,
    location: String?,
): java.net.URI? {
    if (location.isNullOrEmpty()) return null
    return try {
        resolveRedirectLocation(base, location)
    } catch (_: IllegalArgumentException) {
        null
    } catch (_: java.net.URISyntaxException) {
        null
    }
}

/** True when [headers] holds [name] under any ASCII letter case (RFC 9110 section 5.1). */
private fun hasHeader(
    headers: Map<String, String>,
    name: String,
): Boolean = headers.keys.any { it.equals(name, ignoreCase = true) }

/** Generates a UUID v4 string without JVM-specific APIs. */
internal fun generateRequestId(): String {
    val rand = kotlin.random.Random.Default

    fun hex(n: Int) = n.toString(16).padStart(2, '0')
    val b = Array(16) { rand.nextInt(256) }
    b[6] = (b[6] and 0x0f) or 0x40
    b[8] = (b[8] and 0x3f) or 0x80
    return "${hex(b[0])}${hex(b[1])}${hex(b[2])}${hex(b[3])}-" +
        "${hex(b[4])}${hex(b[5])}-" +
        "${hex(b[6])}${hex(b[7])}-" +
        "${hex(b[8])}${hex(b[9])}-" +
        "${hex(b[10])}${hex(b[11])}${hex(b[12])}${hex(b[13])}${hex(b[14])}${hex(b[15])}"
}

/**
 * Best-effort per-part MIME sniffing from a filename's extension. Falls back to
 * `application/octet-stream` for unknown or missing extensions. Used by the
 * multipart builder so that typed-file uploads (PNG, PDF, JSON) carry an
 * accurate per-part Content-Type rather than a blanket octet-stream.
 */
internal fun contentTypeForFilename(filename: String): ContentType {
    val dot = filename.lastIndexOf('.')
    if (dot < 0 || dot == filename.length - 1) return ContentType.Application.OctetStream
    val mime =
        when (filename.substring(dot + 1).lowercase()) {
            "png" -> "image/png"
            "jpg", "jpeg" -> "image/jpeg"
            "gif" -> "image/gif"
            "pdf" -> "application/pdf"
            "json" -> "application/json"
            else -> null
        } ?: return ContentType.Application.OctetStream
    return try {
        ContentType.parse(mime)
    } catch (_: Exception) {
        ContentType.Application.OctetStream
    }
}

/**
 * Parses the `charset=` parameter from a Content-Type header (e.g.
 * `text/plain; charset=ISO-8859-1`). Falls back to UTF-8 when the header is
 * absent, malformed, or names a charset unknown to the JVM. Never throws.
 */
internal fun charsetFor(contentType: String?): java.nio.charset.Charset {
    if (contentType.isNullOrEmpty()) return Charsets.UTF_8
    val afterEquals = contentType.substringAfter("charset=", "")
    if (afterEquals.isEmpty()) return Charsets.UTF_8
    val name = afterEquals.substringBefore(";").trim().trim('"', '\'')
    if (name.isEmpty()) return Charsets.UTF_8
    return try {
        java.nio.charset.Charset
            .forName(name)
    } catch (_: Exception) {
        Charsets.UTF_8
    }
}

/** Returns true if the content type represents text that can be decoded as UTF-8. */
internal fun isTextContentType(contentType: String): Boolean {
    val mediaType =
        contentType
            .split(';')
            .first()
            .trim()
            .lowercase()
    if (mediaType.isEmpty()) return true
    if (mediaType.startsWith("text/")) return true
    return mediaType == "application/json" ||
        mediaType == "application/xml" ||
        mediaType == "application/javascript" ||
        mediaType.endsWith("+json") ||
        mediaType.endsWith("+xml")
}

/**
 * Rejects multipart form field names that would allow Content-Disposition
 * header injection or smuggling. Throws [IllegalArgumentException] when the
 * field name contains CR, LF, or NUL. Must be invoked on every branch of the
 * multipart builder (string, number, boolean, JSON, binary), not just the
 * binary path, because the name is interpolated directly into the
 * `Content-Disposition: form-data; name="..."` header.
 */
internal fun validateMultipartFieldName(fieldName: String?) {
    if (fieldName == null) return
    for (c in fieldName) {
        if (c == '\r' || c == '\n' || c == '\u0000') {
            throw IllegalArgumentException(
                "multipart field name must not contain CR, LF, or NUL characters",
            )
        }
    }
}

/**
 * Rejects multipart filenames that would allow Content-Disposition header
 * injection or smuggling. Throws [IllegalArgumentException] when the filename
 * contains CR, LF, or NUL.
 */
internal fun validateMultipartFilename(filename: String?) {
    if (filename == null) return
    for (c in filename) {
        if (c == '\r' || c == '\n' || c == '\u0000') {
            throw IllegalArgumentException(
                "multipart filename must not contain CR, LF, or NUL characters",
            )
        }
    }
}

/**
 * Builds the `filename=...` directive for a multipart Content-Disposition part.
 * For ASCII-only filenames emits `filename="..."` with quote/backslash escaping.
 * For non-ASCII filenames additionally emits an RFC 5987
 * `filename*=UTF-8''<percent-encoded>` parameter alongside an ASCII fallback
 * (each non-ASCII or control code point replaced with one `_`).
 */
internal fun buildFilenameDirective(filename: String): String {
    val escaped = filename.replace("\\", "\\\\").replace("\"", "\\\"")
    val ascii = filename.all { it.code <= 0x7F }
    if (ascii) {
        return "filename=\"$escaped\""
    }
    // One `_` per Unicode code point (not per UTF-16 unit), so a
    // supplementary character such as an emoji becomes a single `_`.
    val fallback =
        buildString {
            filename.codePoints().forEach { cp ->
                if (cp > 0x7F || cp < 0x20 || cp == 0x7F) {
                    append('_')
                } else {
                    appendCodePoint(cp)
                }
            }
        }.replace("\\", "\\\\").replace("\"", "\\\"")
    val encoded = rfc5987EncodeValue(filename)
    return "filename=\"$fallback\"; filename*=UTF-8''$encoded"
}

/**
 * Percent-encodes every byte that is not an RFC 3986 §2.3 unreserved character,
 * producing the value-chars production of RFC 5987 §3.2.1.
 */
internal fun rfc5987EncodeValue(s: String): String {
    val hex = "0123456789ABCDEF"
    val bytes = s.toByteArray(Charsets.UTF_8)
    val out = StringBuilder(bytes.size * 3)
    for (b in bytes) {
        val u = b.toInt() and 0xFF
        val isUnreserved =
            (u in 'A'.code..'Z'.code) ||
                (u in 'a'.code..'z'.code) ||
                (u in '0'.code..'9'.code) ||
                u == '-'.code ||
                u == '.'.code ||
                u == '_'.code ||
                u == '~'.code
        if (isUnreserved) {
            out.append(u.toChar())
        } else {
            out.append('%').append(hex[u ushr 4]).append(hex[u and 0x0F])
        }
    }
    return out.toString()
}

/** Platform-specific [HttpClient] factory; configured with engine, TLS, proxy, and common plugins. */
internal expect fun buildPlatformHttpClient(options: TransportOptions): HttpClient
